// Normalização do webhook da Evolution API
const body = $input.first().json.body;

// --- Cenário: recebimento de mensagem via Evolution ---
let event_type = body?.event || '';
let data = body?.data || body || {};
let instance = body?.instance || data?.instance || '';
let sender = body?.sender || '';

// Dados do contato
let remoteJid = data?.key?.remoteJid || data?.remoteJid || '';
let pushName = data?.pushName || data?.key?.pushName || '';
let profilePicUrl = '';

// Dados da mensagem
let messageType = 'unknown';
let messageContent = '';
let messageId = data?.key?.id || '';
let fromMe = data?.key?.fromMe || false;
let timestamp = data?.messageTimestamp || Math.floor(Date.now() / 1000);

// Detectar tipo
if (data?.message?.conversation || data?.message?.extendedTextMessage?.text) {
  messageType = 'text';
  messageContent = data?.message?.conversation || data?.message?.extendedTextMessage?.text || '';
} else if (data?.message?.audioMessage) {
  messageType = 'audio';
  messageContent = '[Áudio recebido]';
} else if (data?.message?.imageMessage) {
  messageType = 'image';
  messageContent = data?.message?.imageMessage?.caption || '[Imagem recebida]';
} else if (data?.message?.documentMessage) {
  messageType = 'document';
  let mimetype = data?.message?.documentMessage?.mimetype || '';
  if (mimetype.includes('pdf')) {
    messageType = 'pdf';
  }
  messageContent = data?.message?.documentMessage?.fileName || '[Documento recebido]';
} else if (data?.message?.videoMessage) {
  messageType = 'video';
  messageContent = '[Vídeo recebido]';
} else if (data?.message?.stickerMessage) {
  messageType = 'sticker';
  messageContent = '[Sticker]';
} else if (data?.message?.reactionMessage) {
  messageType = 'reaction';
  messageContent = data?.message?.reactionMessage?.text || '';
} else if (data?.message?.locationMessage) {
  messageType = 'location';
  messageContent = '[Localização]';
} else if (data?.message?.contactMessage || data?.message?.contactsArrayMessage) {
  messageType = 'contact';
  messageContent = '[Contato compartilhado]';
}

// Detectar origem (Meta Ads vs Orgânico)
let ctwaClid = data?.contextInfo?.externalAdReply?.sourceId || '';
let isFromAd = !!ctwaClid;
let origem = isFromAd ? 'whatsapp_ads' : 'whatsapp_organico';

// Detectar LID (Lead from Instagram/Facebook)
let lidId = '';
if (remoteJid && remoteJid.includes('@lid')) {
  lidId = remoteJid;
  origem = 'meta_ads_lid';
}

// UTM data from ctwa
let utmSource = '';
let utmMedium = '';
let utmCampaign = '';
let utmContent = '';

// Extrair telefone formatado
let telefone = remoteJid ? remoteJid.split('@')[0] : '';
let telefoneFormatado = telefone;
if (telefone.length >= 12) {
  telefoneFormatado = `+${telefone.substring(0, 2)} (${telefone.substring(2, 4)}) ${telefone.substring(4, 9)}-${telefone.substring(9)}`;
}

return {
  json: {
    // Identificação
    remote_jid: remoteJid,
    lid_id: lidId,
    instance: instance,
    sender: sender,
    push_name: pushName,
    profile_picture_url: profilePicUrl,

    // Mensagem
    message_type: messageType,
    message_content: messageContent,
    message_id: messageId,
    from_me: fromMe,
    timestamp: timestamp,

    // Contato
    telefone: telefone,
    telefone_formatado: telefoneFormatado,

    // Rastreamento
    origem: origem,
    ctwa_clid: ctwaClid,
    is_from_ad: isFromAd,
    utm_source: utmSource,
    utm_medium: utmMedium,
    utm_campaign: utmCampaign,
    utm_content: utmContent,

    // Meta
    event_type: event_type,
    raw_data: data
  }
};

// Verificar se o agente está ativo para este lead via Redis
// Se agente_ativo = false, o lead está sendo atendido por um humano
const remoteJid = $input.first().json.remote_jid;
const instance = $input.first().json.instance;
const botStatusKey = `numa:bot_status:${instance}:${remoteJid}`;

// Consultar Redis (Upstash)
const redisUrl = $env.UPSTASH_REDIS_URL || '';
const redisToken = $env.UPSTASH_REDIS_TOKEN || '';

let agenteAtivo = true;

if (redisUrl && redisToken) {
  try {
    const response = await fetch(`${redisUrl}/get/${botStatusKey}`, {
      headers: { 'Authorization': `Bearer ${redisToken}` }
    });
    const data = await response.json();
    if (data.result === 'disabled') {
      agenteAtivo = false;
    }
  } catch (err) {
    console.log('Redis check failed, assuming active:', err.message);
  }
}

return {
  json: {
    ...$input.first().json,
    agente_ativo: agenteAtivo
  }
};

// Mensagem de texto — passa direto para o buffer
return {
  json: {
    ...$input.first().json,
    processed_content: $input.first().json.message_content,
    content_type: 'text'
  }
};

// Transcrever áudio via Whisper (OpenAI)
const remoteJid = $input.first().json.remote_jid;
const instance = $input.first().json.instance;
const messageId = $input.first().json.message_id;

// Baixar áudio da Evolution API
const evolutionUrl = $env.EVOLUTION_API_URL || '';
const evolutionKey = $env.EVOLUTION_API_KEY || '';

try {
  // 1. Fazer download do media via Evolution
  const mediaResp = await fetch(`${evolutionUrl}/chat/getBase64FromMediaMessage/${instance}`, {
    method: 'POST',
    headers: {
      'apikey': evolutionKey,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      message: { key: { id: messageId, remoteJid: remoteJid } },
      convertToMp4: false
    })
  });
  const mediaData = await mediaResp.json();
  const base64Audio = mediaData.base64 || '';
  const mimetype = mediaData.mimetype || 'audio/ogg';

  if (!base64Audio) {
    return { json: { ...$input.first().json, processed_content: '[Áudio não pôde ser processado]', content_type: 'audio_failed' } };
  }

  // 2. Converter base64 para buffer
  const audioBuffer = Buffer.from(base64Audio, 'base64');

  // 3. Enviar para Whisper (OpenAI)
  const FormData = (await import('form-data')).default;
  const form = new FormData();
  form.append('file', audioBuffer, { filename: 'audio.ogg', contentType: mimetype });
  form.append('model', 'whisper-1');
  form.append('language', 'pt');

  const whisperResp = await fetch('https://api.openai.com/v1/audio/transcriptions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${$env.OPENAI_API_KEY}`,
      ...form.getHeaders()
    },
    body: form
  });
  const transcription = await whisperResp.json();

  return {
    json: {
      ...$input.first().json,
      processed_content: `[Transcrição de áudio]: ${transcription.text || '[Não foi possível transcrever]'}`,
      content_type: 'audio_transcribed'
    }
  };
} catch (err) {
  return {
    json: {
      ...$input.first().json,
      processed_content: `[Erro ao processar áudio]: ${err.message}`,
      content_type: 'audio_error'
    }
  };
}

// Analisar imagem via GPT-4o Vision
const remoteJid = $input.first().json.remote_jid;
const instance = $input.first().json.instance;
const messageId = $input.first().json.message_id;
const caption = $input.first().json.message_content || '';

const evolutionUrl = $env.EVOLUTION_API_URL || '';
const evolutionKey = $env.EVOLUTION_API_KEY || '';

try {
  // 1. Download da imagem via Evolution
  const mediaResp = await fetch(`${evolutionUrl}/chat/getBase64FromMediaMessage/${instance}`, {
    method: 'POST',
    headers: {
      'apikey': evolutionKey,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      message: { key: { id: messageId, remoteJid: remoteJid } },
      convertToMp4: false
    })
  });
  const mediaData = await mediaResp.json();
  const base64Image = mediaData.base64 || '';
  const mimetype = mediaData.mimetype || 'image/jpeg';

  if (!base64Image) {
    return { json: { ...$input.first().json, processed_content: '[Imagem não pôde ser processada]', content_type: 'image_failed' } };
  }

  // 2. Enviar para GPT-4o Vision
  const visionResp = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${$env.OPENAI_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'gpt-4o',
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: `Analise esta imagem no contexto de gestão financeira empresarial. Se for um comprovante, nota fiscal, boleto ou extrato, extraia todas as informações relevantes (valores, datas, fornecedor/cliente, CNPJ, descrição). Se for outra coisa, descreva brevemente.${caption ? ` O usuário enviou junto a legenda: "${caption}"` : ''}`
            },
            {
              type: 'image_url',
              image_url: { url: `data:${mimetype};base64,${base64Image}` }
            }
          ]
        }
      ],
      max_tokens: 1000
    })
  });
  const visionData = await visionResp.json();
  const analysis = visionData.choices?.[0]?.message?.content || '[Falha na análise]';

  return {
    json: {
      ...$input.first().json,
      processed_content: `[Análise de imagem]: ${analysis}`,
      content_type: 'image_analyzed'
    }
  };
} catch (err) {
  return {
    json: {
      ...$input.first().json,
      processed_content: `[Erro ao processar imagem]: ${err.message}`,
      content_type: 'image_error'
    }
  };
}

// Processar PDF via OCR (GPT-4o Vision com cada página)
const remoteJid = $input.first().json.remote_jid;
const instance = $input.first().json.instance;
const messageId = $input.first().json.message_id;

const evolutionUrl = $env.EVOLUTION_API_URL || '';
const evolutionKey = $env.EVOLUTION_API_KEY || '';

try {
  const mediaResp = await fetch(`${evolutionUrl}/chat/getBase64FromMediaMessage/${instance}`, {
    method: 'POST',
    headers: {
      'apikey': evolutionKey,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      message: { key: { id: messageId, remoteJid: remoteJid } },
      convertToMp4: false
    })
  });
  const mediaData = await mediaResp.json();
  const base64Pdf = mediaData.base64 || '';

  if (!base64Pdf) {
    return { json: { ...$input.first().json, processed_content: '[PDF não pôde ser processado]', content_type: 'pdf_failed' } };
  }

  // Enviar o PDF como imagem para GPT-4o (primeira página)
  const visionResp = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${$env.OPENAI_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'gpt-4o',
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: 'Este é um documento PDF de contexto financeiro empresarial. Extraia todas as informações relevantes: valores, datas, fornecedor/cliente, CNPJ, descrição dos itens, e qualquer dado financeiro útil. Organize a informação de forma clara.'
            },
            {
              type: 'image_url',
              image_url: { url: `data:application/pdf;base64,${base64Pdf}` }
            }
          ]
        }
      ],
      max_tokens: 2000
    })
  });
  const visionData = await visionResp.json();
  const extraction = visionData.choices?.[0]?.message?.content || '[Falha na extração]';

  return {
    json: {
      ...$input.first().json,
      processed_content: `[Extração de PDF]: ${extraction}`,
      content_type: 'pdf_extracted'
    }
  };
} catch (err) {
  return {
    json: {
      ...$input.first().json,
      processed_content: `[Erro ao processar PDF]: ${err.message}`,
      content_type: 'pdf_error'
    }
  };
}

// Documento genérico — apenas notifica que recebeu
return {
  json: {
    ...$input.first().json,
    processed_content: `[Documento recebido: ${$input.first().json.message_content}]. Para melhor processamento, envie como PDF ou imagem.`,
    content_type: 'document_raw'
  }
};

// Buffer de mensagens — agrupa mensagens consecutivas do mesmo lead
// antes de enviar ao agente (evita múltiplas chamadas à IA)
const redisUrl = $env.UPSTASH_REDIS_URL || '';
const redisToken = $env.UPSTASH_REDIS_TOKEN || '';
const remoteJid = $input.first().json.remote_jid;
const instance = $input.first().json.instance;
const bufferKey = `numa:buffer:${instance}:${remoteJid}`;
const content = $input.first().json.processed_content || $input.first().json.message_content;
const BUFFER_WAIT_SECONDS = 8;

try {
  // Adicionar mensagem ao buffer (Redis LIST)
  await fetch(`${redisUrl}/rpush/${bufferKey}/${encodeURIComponent(content)}`, {
    headers: { 'Authorization': `Bearer ${redisToken}` }
  });

  // Definir TTL no buffer
  await fetch(`${redisUrl}/expire/${bufferKey}/${BUFFER_WAIT_SECONDS + 10}`, {
    headers: { 'Authorization': `Bearer ${redisToken}` }
  });

  // Definir lock com timestamp
  const lockKey = `numa:buffer_lock:${instance}:${remoteJid}`;
  const now = Date.now();
  await fetch(`${redisUrl}/set/${lockKey}/${now}/EX/${BUFFER_WAIT_SECONDS + 5}`, {
    headers: { 'Authorization': `Bearer ${redisToken}` }
  });

  return {
    json: {
      ...$input.first().json,
      buffer_key: bufferKey,
      lock_key: lockKey,
      lock_timestamp: now,
      buffer_wait_seconds: BUFFER_WAIT_SECONDS
    }
  };
} catch (err) {
  // Fallback: enviar direto sem buffer
  return {
    json: {
      ...$input.first().json,
      processed_content: content,
      buffer_key: '',
      buffered: false
    }
  };
}

// Comparar lock — só processa se for a mensagem mais recente
const redisUrl = $env.UPSTASH_REDIS_URL || '';
const redisToken = $env.UPSTASH_REDIS_TOKEN || '';
const lockKey = $input.first().json.lock_key;
const myTimestamp = $input.first().json.lock_timestamp;

try {
  const response = await fetch(`${redisUrl}/get/${lockKey}`, {
    headers: { 'Authorization': `Bearer ${redisToken}` }
  });
  const data = await response.json();
  const currentLock = parseInt(data.result || '0');

  if (currentLock !== myTimestamp) {
    // Outro processamento mais recente vai cuidar
    return { json: { should_process: false } };
  }

  // Eu sou o mais recente — consumir todas as mensagens do buffer
  const bufferKey = $input.first().json.buffer_key;
  const bufferResp = await fetch(`${redisUrl}/lrange/${bufferKey}/0/-1`, {
    headers: { 'Authorization': `Bearer ${redisToken}` }
  });
  const bufferData = await bufferResp.json();
  const messages = (bufferData.result || []).map(m => decodeURIComponent(m));

  // Limpar buffer
  await fetch(`${redisUrl}/del/${bufferKey}`, {
    headers: { 'Authorization': `Bearer ${redisToken}` }
  });
  await fetch(`${redisUrl}/del/${lockKey}`, {
    headers: { 'Authorization': `Bearer ${redisToken}` }
  });

  return {
    json: {
      ...$input.first().json,
      should_process: true,
      processed_content: messages.join('\n'),
      message_count: messages.length
    }
  };
} catch (err) {
  return {
    json: {
      ...$input.first().json,
      should_process: true,
      processed_content: $input.first().json.processed_content || $input.first().json.message_content,
      message_count: 1
    }
  };
}

// Upsert Lead no Supabase + buscar contexto da empresa
const supabaseUrl = $env.SUPABASE_URL || '';
const supabaseKey = $env.SUPABASE_SERVICE_KEY || '';
const data = $input.first().json;

const headers = {
  'apikey': supabaseKey,
  'Authorization': `Bearer ${supabaseKey}`,
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

try {
  // 1. Buscar lead existente por remote_jid
  let lead = null;
  const searchField = data.lid_id ? 'lid_id' : 'remote_jid';
  const searchValue = data.lid_id || data.remote_jid;

  const searchResp = await fetch(
    `${supabaseUrl}/rest/v1/leads?${searchField}=eq.${encodeURIComponent(searchValue)}&select=*`,
    { headers }
  );
  const leads = await searchResp.json();
  lead = leads?.[0] || null;

  if (lead) {
    // 2a. Atualizar lead existente
    const updateData = {
      nome: data.push_name || lead.nome,
      username_whatsapp: data.push_name || lead.username_whatsapp,
      ultima_mensagem_at: new Date().toISOString(),
      total_mensagens_recebidas: (lead.total_mensagens_recebidas || 0) + (data.message_count || 1),
      updated_at: new Date().toISOString()
    };

    // Atualizar telefone se era LID e agora tem telefone
    if (data.telefone && !lead.telefone && !data.lid_id) {
      updateData.telefone = data.telefone;
      updateData.telefone_formatado = data.telefone_formatado;
    }

    // Atualizar remote_jid se era LID
    if (lead.lid_id && data.remote_jid && !data.remote_jid.includes('@lid')) {
      updateData.remote_jid = data.remote_jid;
      updateData.telefone = data.telefone;
      updateData.telefone_formatado = data.telefone_formatado;
    }

    await fetch(
      `${supabaseUrl}/rest/v1/leads?id=eq.${lead.id}`,
      {
        method: 'PATCH',
        headers: { ...headers, 'Prefer': 'return=representation' },
        body: JSON.stringify(updateData)
      }
    );

    lead = { ...lead, ...updateData };
  } else {
    // 2b. Criar novo lead
    const newLead = {
      remote_jid: data.remote_jid,
      lid_id: data.lid_id || null,
      telefone: data.telefone || null,
      telefone_formatado: data.telefone_formatado || null,
      nome: data.push_name || null,
      username_whatsapp: data.push_name || null,
      instancia_evolution: data.instance || 'default',
      origem: data.origem || 'whatsapp_organico',
      ctwa_clid: data.ctwa_clid || null,
      utm_source: data.utm_source || null,
      utm_medium: data.utm_medium || null,
      utm_campaign: data.utm_campaign || null,
      utm_content: data.utm_content || null,
      status: 'novo',
      funnel_stage: 'awareness',
      primeira_mensagem_at: new Date().toISOString(),
      ultima_mensagem_at: new Date().toISOString(),
      total_mensagens_recebidas: 1
    };

    const createResp = await fetch(
      `${supabaseUrl}/rest/v1/leads`,
      {
        method: 'POST',
        headers: { ...headers, 'Prefer': 'return=representation' },
        body: JSON.stringify(newLead)
      }
    );
    const created = await createResp.json();
    lead = created?.[0] || newLead;
  }

  // 3. Buscar contexto da empresa (se lead vinculado)
  let companyContext = null;
  if (lead.company_id) {
    const compResp = await fetch(
      `${supabaseUrl}/rest/v1/companies?id=eq.${lead.company_id}&select=id,name,trading_name,segment,currency,currency_symbol`,
      { headers }
    );
    const companies = await compResp.json();
    companyContext = companies?.[0] || null;
  }

  // 4. Buscar session_id para memória do agente
  let sessionId = lead.session_id;
  if (!sessionId) {
    sessionId = `numa_${lead.id}_${Date.now()}`;
    await fetch(
      `${supabaseUrl}/rest/v1/leads?id=eq.${lead.id}`,
      {
        method: 'PATCH',
        headers,
        body: JSON.stringify({ session_id: sessionId })
      }
    );
  }

  return {
    json: {
      ...data,
      lead: lead,
      company: companyContext,
      session_id: sessionId,
      lead_id: lead.id,
      company_id: lead.company_id
    }
  };
} catch (err) {
  return {
    json: {
      ...data,
      lead: null,
      company: null,
      session_id: `fallback_${Date.now()}`,
      error_lead: err.message
    }
  };
}

// Tools do agente NUMA — Supabase HTTP
// Cada ferramenta é uma function que o agente pode chamar

const supabaseUrl = $env.SUPABASE_URL || '';
const supabaseKey = $env.SUPABASE_SERVICE_KEY || '';
const companyId = $input.first().json.company_id;

const headers = {
  'apikey': supabaseKey,
  'Authorization': `Bearer ${supabaseKey}`,
  'Content-Type': 'application/json'
};

const toolName = $input.first().json.tool_name;
const toolInput = $input.first().json.tool_input || {};

try {
  let result = null;

  switch (toolName) {
    case 'registrar_transacao': {
      const { descricao, valor, tipo, categoria, data_transacao, conta_bancaria } = toolInput;
      const body = {
        company_id: companyId,
        description: descricao,
        amount: Math.abs(valor),
        type: tipo || (valor < 0 ? 'despesa' : 'receita'),
        category_name: categoria || 'Geral',
        date: data_transacao || new Date().toISOString().split('T')[0],
        status: 'realizado'
      };
      const resp = await fetch(`${supabaseUrl}/rest/v1/transactions`, {
        method: 'POST',
        headers: { ...headers, 'Prefer': 'return=representation' },
        body: JSON.stringify(body)
      });
      result = await resp.json();
      break;
    }

    case 'buscar_saldo_contas': {
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/bank_accounts?company_id=eq.${companyId}&is_active=eq.true&select=name,current_balance,bank_name,account_type`,
        { headers }
      );
      result = await resp.json();
      break;
    }

    case 'listar_transacoes': {
      const { periodo, tipo, limite } = toolInput;
      let url = `${supabaseUrl}/rest/v1/transactions?company_id=eq.${companyId}&select=description,amount,type,date,category_name,status&order=date.desc&limit=${limite || 10}`;
      if (tipo) url += `&type=eq.${tipo}`;
      if (periodo) {
        const start = new Date();
        if (periodo === 'semana') start.setDate(start.getDate() - 7);
        else if (periodo === 'mes') start.setMonth(start.getMonth() - 1);
        else if (periodo === 'trimestre') start.setMonth(start.getMonth() - 3);
        url += `&date=gte.${start.toISOString().split('T')[0]}`;
      }
      const resp = await fetch(url, { headers });
      result = await resp.json();
      break;
    }

    case 'consultar_contas_pagar': {
      const { dias } = toolInput;
      const dataLimite = new Date();
      dataLimite.setDate(dataLimite.getDate() + (dias || 30));
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/payables?company_id=eq.${companyId}&status=eq.pendente&due_date=lte.${dataLimite.toISOString().split('T')[0]}&select=description,amount,due_date,supplier_name,status,category_name&order=due_date.asc&limit=15`,
        { headers }
      );
      result = await resp.json();
      break;
    }

    case 'consultar_contas_receber': {
      const { dias } = toolInput;
      const dataLimite = new Date();
      dataLimite.setDate(dataLimite.getDate() + (dias || 30));
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/receivables?company_id=eq.${companyId}&status=eq.pendente&due_date=lte.${dataLimite.toISOString().split('T')[0]}&select=description,amount,due_date,customer_name,status,category_name&order=due_date.asc&limit=15`,
        { headers }
      );
      result = await resp.json();
      break;
    }

    case 'buscar_categorias': {
      const { tipo } = toolInput;
      let url = `${supabaseUrl}/rest/v1/categories?company_id=eq.${companyId}&is_active=eq.true&select=name,type,color,icon`;
      if (tipo) url += `&type=eq.${tipo}`;
      const resp = await fetch(url, { headers });
      result = await resp.json();
      break;
    }

    case 'resumo_financeiro': {
      const { mes, ano } = toolInput;
      const targetMonth = mes || (new Date().getMonth() + 1);
      const targetYear = ano || new Date().getFullYear();
      const startDate = `${targetYear}-${String(targetMonth).padStart(2, '0')}-01`;
      const endDate = new Date(targetYear, targetMonth, 0).toISOString().split('T')[0];

      const resp = await fetch(
        `${supabaseUrl}/rest/v1/transactions?company_id=eq.${companyId}&date=gte.${startDate}&date=lte.${endDate}&select=amount,type,category_name`,
        { headers }
      );
      const transactions = await resp.json();

      let totalReceitas = 0;
      let totalDespesas = 0;
      const porCategoria = {};

      for (const t of transactions) {
        if (t.type === 'receita') totalReceitas += t.amount;
        else totalDespesas += t.amount;
        const cat = t.category_name || 'Sem categoria';
        porCategoria[cat] = (porCategoria[cat] || 0) + t.amount;
      }

      result = {
        periodo: `${String(targetMonth).padStart(2, '0')}/${targetYear}`,
        total_receitas: totalReceitas,
        total_despesas: totalDespesas,
        saldo: totalReceitas - totalDespesas,
        total_transacoes: transactions.length,
        por_categoria: porCategoria
      };
      break;
    }

    case 'buscar_clientes': {
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/customers?company_id=eq.${companyId}&is_active=eq.true&select=name,document,email,phone&limit=20`,
        { headers }
      );
      result = await resp.json();
      break;
    }

    case 'buscar_fornecedores': {
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/suppliers?company_id=eq.${companyId}&is_active=eq.true&select=name,document,email,phone&limit=20`,
        { headers }
      );
      result = await resp.json();
      break;
    }

    case 'desativar_agente': {
      const redisUrl = $env.UPSTASH_REDIS_URL || '';
      const redisToken = $env.UPSTASH_REDIS_TOKEN || '';
      const remoteJid = $input.first().json.remote_jid;
      const instance = $input.first().json.instance;
      const botStatusKey = `numa:bot_status:${instance}:${remoteJid}`;

      // Desativar por 2 horas
      await fetch(`${redisUrl}/set/${botStatusKey}/disabled/EX/7200`, {
        headers: { 'Authorization': `Bearer ${redisToken}` }
      });

      // Atualizar lead no Supabase
      const leadId = $input.first().json.lead_id;
      if (leadId) {
        await fetch(`${supabaseUrl}/rest/v1/leads?id=eq.${leadId}`, {
          method: 'PATCH',
          headers,
          body: JSON.stringify({
            agente_ativo: false,
            agente_desativado_at: new Date().toISOString(),
            agente_desativado_motivo: toolInput.motivo || 'Solicitado pelo cliente'
          })
        });
      }

      result = { status: 'agente_desativado', duracao: '2 horas', motivo: toolInput.motivo };
      break;
    }

    default:
      result = { error: `Ferramenta '${toolName}' não reconhecida` };
  }

  return { json: { result: JSON.stringify(result) } };
} catch (err) {
  return { json: { result: JSON.stringify({ error: err.message }) } };
}

// Humanizar resposta — quebrar em mensagens menores para WhatsApp
const resposta = $input.first().json.output || $input.first().json.text || '';
const MAX_CHARS = 240;

if (!resposta || resposta.trim() === '') {
  return { json: { messages: ['Desculpe, não consegui processar sua solicitação. Pode repetir?'] } };
}

// Quebrar por parágrafos primeiro
const paragraphs = resposta.split('\n\n').filter(p => p.trim());
const messages = [];

for (const para of paragraphs) {
  if (para.length <= MAX_CHARS) {
    messages.push(para.trim());
  } else {
    // Quebrar por frases
    const sentences = para.split(/(?<=[.!?])\s+/);
    let currentChunk = '';

    for (const sentence of sentences) {
      if ((currentChunk + ' ' + sentence).length > MAX_CHARS && currentChunk) {
        messages.push(currentChunk.trim());
        currentChunk = sentence;
      } else {
        currentChunk = currentChunk ? currentChunk + ' ' + sentence : sentence;
      }
    }
    if (currentChunk.trim()) {
      messages.push(currentChunk.trim());
    }
  }
}

// Retornar array de mensagens
return messages.map(msg => ({ json: { message: msg } }));

// Simular digitação antes de enviar (delays entre mensagens)
const message = $input.first().json.message;
const remoteJid = $('lead-crud').first().json.remote_jid || $('normalize-webhook').first().json.remote_jid;
const instance = $('lead-crud').first().json.instance || $('normalize-webhook').first().json.instance;
const evolutionUrl = $env.EVOLUTION_API_URL || '';
const evolutionKey = $env.EVOLUTION_API_KEY || '';

try {
  // 1. Enviar presença "composing" (digitando)
  await fetch(`${evolutionUrl}/chat/presence/${instance}`, {
    method: 'POST',
    headers: {
      'apikey': evolutionKey,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      number: remoteJid,
      presence: 'composing',
      delay: Math.min(message.length * 30, 3000) // Delay proporcional ao tamanho
    })
  });

  // 2. Aguardar (simular digitação humana)
  const typingDelay = Math.min(Math.max(message.length * 25, 800), 3000);
  await new Promise(resolve => setTimeout(resolve, typingDelay));

  // 3. Enviar mensagem
  const sendResp = await fetch(`${evolutionUrl}/message/sendText/${instance}`, {
    method: 'POST',
    headers: {
      'apikey': evolutionKey,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      number: remoteJid,
      text: message,
      delay: 100
    })
  });
  const sendResult = await sendResp.json();

  // 4. Atualizar contador de mensagens enviadas no lead
  const supabaseUrl = $env.SUPABASE_URL || '';
  const supabaseKey = $env.SUPABASE_SERVICE_KEY || '';
  const leadId = $('lead-crud').first().json.lead_id;

  if (leadId) {
    await fetch(`${supabaseUrl}/rest/v1/rpc/increment_lead_sent_count`, {
      method: 'POST',
      headers: {
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ p_lead_id: leadId })
    }).catch(() => {}); // Non-critical
  }

  return { json: { sent: true, message: message, to: remoteJid } };
} catch (err) {
  return { json: { sent: false, error: err.message, message: message } };
}
